from collections import Counter, deque
from pathlib import Path
import json

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False]*w for _ in range(h)]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = [(r,c)]; seen[r][c] = True
            for y,x in q:
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and grid[ny][nx]==color:
                        seen[ny][nx]=True; q.append((ny,nx))
            if len(q)==1:
                counts=Counter(grid[ny][nx] for dy,dx in ((1,0),(-1,0),(0,1),(0,-1))
                    if 0<=(ny:=r+dy)<h and 0<=(nx:=c+dx)<w)
                if counts:
                    maxn=max(counts.values())
                    winners=[v for v,n in counts.items() if n==maxn]
                    if len(winners)>1 and bg in winners:
                        nonbg=[v for v in winners if v!=bg]
                        if nonbg: out[r][c]=nonbg[0]
                    else:
                        out[r][c]=winners[0]
    return out

